  if (r.cost !== undefined && r.cost !== null && String(r.cost).trim() !== '') o.cost = Math.round(parseNum_(r.cost));
  if (r.coef_own !== undefined && r.coef_own !== null && String(r.coef_own).trim() !== '') o.coef_own = Math.max(0, num_(parseNum_(r.coef_own)));
