ACTIONS.getConfig = function (u) { need_(u, 'config', 'view'); var c = Object.assign({}, cfg_()); c.cost_types = costTypes_(); return { cfg: c, users: readTable_('USERS'), roles: ROLES, version: APP_VERSION }; };
